<script setup lang="ts">
const supabase=useSupabaseClient();const rows=ref<any[]>([]);const switches=ref<any[]>([]);const points=ref<any[]>([]);const show=ref(false);const form=reactive<any>({tested_at:new Date().toISOString().slice(0,10),switch_id:'',port_number:null,data_point_id:'',issue_test:'',result:'',action_taken:'',outstanding:false,assigned_to:'',resolved_date:'',notes:''});async function load(){const [{data:r},{data:s},{data:d}]=await Promise.all([supabase.from('testing_faults').select('*,switches(switch_code),data_points(data_point_code)').order('tested_at',{ascending:false}),supabase.from('switches').select('id,switch_code').order('switch_code'),supabase.from('data_points').select('id,data_point_code').order('data_point_code')]);rows.value=r||[];switches.value=s||[];points.value=d||[]}async function save(){await supabase.from('testing_faults').insert({...form,switch_id:form.switch_id||null,data_point_id:form.data_point_id||null,resolved_date:form.resolved_date||null});show.value=false;await load()}async function resolve(r:any){await supabase.from('testing_faults').update({outstanding:false,resolved_date:new Date().toISOString().slice(0,10)}).eq('id',r.id);await load()}onMounted(load)
</script><template><section><div class="pagehead"><div><h2>Testing & Faults</h2><p>Record testing, faults, actions and outstanding work.</p></div><button class="btn" @click="show=true">+ Record Test / Fault</button></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Switch / Port</th><th>Data Point</th><th>Issue / Test</th><th>Result</th><th>Assigned</th><th>Status</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.tested_at}}</td><td>{{r.switches?.switch_code||'—'}} / {{r.port_number||'—'}}</td><td>{{r.data_points?.data_point_code||'—'}}</td><td>{{r.issue_test||'—'}}</td><td>{{r.result||'—'}}</td><td>{{r.assigned_to||'—'}}</td><td><button v-if="r.outstanding" class="btn tiny" @click="resolve(r)">Resolve</button><span v-else class="badge">Resolved</span></td></tr></tbody></table></div><AppModal v-if="show" title="Test / Fault" @close="show=false"><form class="formgrid" @submit.prevent="save"><label>Date<input v-model="form.tested_at" type="date" required></label><label>Switch<select v-model="form.switch_id"><option value="">None</option><option v-for="s in switches" :value="s.id">{{s.switch_code}}</option></select></label><label>Port<input v-model.number="form.port_number" type="number"></label><label>Data Point<select v-model="form.data_point_id"><option value="">None</option><option v-for="d in points" :value="d.id">{{d.data_point_code}}</option></select></label><label class="full">Issue / Test<textarea v-model="form.issue_test"></textarea></label><label>Result<input v-model="form.result"></label><label>Assigned To<input v-model="form.assigned_to"></label><label class="full">Action Taken<textarea v-model="form.action_taken"></textarea></label><label><input v-model="form.outstanding" type="checkbox"> Outstanding</label><label>Resolved Date<input v-model="form.resolved_date" type="date"></label><label class="full">Notes<textarea v-model="form.notes"></textarea></label><div class="full right"><button class="btn secondary" type="button" @click="show=false">Cancel</button> <button class="btn">Save</button></div></form></AppModal></section></template>
